def valid_word(word):
    # Check minimum length
    if len(word) < 3:
        return False

    # Define vowels
    vowels = set('aeiouAEIOU')

    # Track if we have at least one vowel and one consonant
    has_vowel = False
    has_consonant = False

    for char in word:
        # Check if character is alphanumeric (only digits and English letters allowed)
        if not (char.isdigit() or char.isalpha()):
            return False

        # Check for vowels and consonants (only letters matter for this)
        if char.isalpha():
            if char in vowels:
                has_vowel = True
            else:
                has_consonant = True

    # Must have at least one vowel AND one consonant
    return has_vowel and has_consonant
