def latest_time(s):
    # Convert string to list for easier manipulation
    time_list = list(s)

    # Handle hour part (positions 0 and 1)
    # First hour digit (index 0)
    if time_list[0] == '?':
        if time_list[1] == '?' or int(time_list[1]) <= 1:
            time_list[0] = '1'
        else:
            time_list[0] = '0'

    # Second hour digit (index 1)
    if time_list[1] == '?':
        if time_list[0] == '1':
            time_list[1] = '1'  # max digit when first digit is 1 is 1 (for 10, 11)
        else:  # time_list[0] == '0'
            time_list[1] = '9'  # max digit when first digit is 0 is 9 (for 09)

    # Handle minute part (positions 3 and 4)
    # First minute digit (index 3)
    if time_list[3] == '?':
        time_list[3] = '5'  # max first minute digit is always 5

    # Second minute digit (index 4)
    if time_list[4] == '?':
        time_list[4] = '9'  # max second minute digit is always 9

    return ''.join(time_list)
