def last_non_empty_string(s: str) -> str:
    # Count frequency of each character
    freq = [0] * 26
    for char in s:
        freq[ord(char) - ord('a')] += 1

    # Find the maximum frequency
    max_freq = max(freq)

    # The characters that appear with max frequency will be removed last
    # So the answer is the subsequence of s containing only those characters
    result = []
    for char in s:
        if freq[ord(char) - ord('a')] == max_freq:
            result.append(char)

    return ''.join(result)
