def smallestString(s: str) -> str:
    n = len(s)
    s_list = list(s)

    # Find the first non-'a' character
    i = 0
    while i < n and s_list[i] == 'a':
        i += 1

    # If all characters are 'a', convert the last 'a' to 'z'
    if i == n:
        s_list[-1] = 'z'
        return ''.join(s_list)

    # Starting from the first non-'a', convert characters until we hit 'a' again
    j = i
    while j < n and s_list[j] != 'a':
        s_list[j] = chr(ord(s_list[j]) - 1)
        j += 1

    return ''.join(s_list)
```

