def count_right_triangles(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    # Count ones in each row and column
    row_counts = [0] * m
    col_counts = [0] * n

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                row_counts[i] += 1
                col_counts[j] += 1

    # For each cell (i, j) that is 1, count right triangles where (i, j) is the right angle
    # A right triangle with right angle at (i, j) needs:
    # - One other 1 in the same row (i, k) where k != j
    # - One other 1 in the same column (k, j) where k != i
    # Number of such triangles = (row_count[i] - 1) * (col_count[j] - 1)

    total = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                # Count triangles with right angle at (i, j)
                total += (row_counts[i] - 1) * (col_counts[j] - 1)

    return total
```

