def sort_vowels(s: str) -> str:
    vowels = set('aeiouAEIOU')

    # Collect all vowels from the string
    vowel_chars = []
    for char in s:
        if char in vowels:
            vowel_chars.append(char)

    # Sort the vowels by their ASCII values
    vowel_chars.sort()

    # Build the result string
    result = []
    vowel_index = 0

    for char in s:
        if char in vowels:
            result.append(vowel_chars[vowel_index])
            vowel_index += 1
        else:
            result.append(char)

    return ''.join(result)
