import math
from functools import reduce

def kthSmallestAmount(coins, k):
    # Remove duplicates and sort
    coins = sorted(set(coins))

    # Helper function to compute LCM of two numbers
    def lcm(a, b):
        return a * b // math.gcd(a, b)

    # Helper function to count how many numbers <= x can be formed
    def count(x):
        if x <= 0:
            return 0

        total = 0
        n = len(coins)
        # Iterate over all non-empty subsets using bitmasks
        for mask in range(1, 1 << n):
            # Calculate LCM of the subset
            current_lcm = 1
            bits = 0
            for i in range(n):
                if mask & (1 << i):
                    bits += 1
                    current_lcm = lcm(current_lcm, coins[i])
                    # If LCM exceeds x, no multiples will be <= x
                    if current_lcm > x:
                        break

            if current_lcm > x:
                continue

            # Count multiples of current_lcm <= x
            multiples = x // current_lcm

            # Inclusion-exclusion principle: add for odd number of elements, subtract for even
            if bits % 2 == 1:
                total += multiples
            else:
                total -= multiples

        return total

    # Binary search for the k-th smallest amount
    # Lower bound: minimum coin value
    # Upper bound: k * min(coins) is a safe upper bound (worst case: only smallest coin used)
    left, right = min(coins), k * min(coins)

    while left < right:
        mid = (left + right) // 2
        if count(mid) >= k:
            right = mid
        else:
            left = mid + 1

    return left
```

