def permutation_difference(s: str, t: str) -> int:
    # Create a dictionary to store the index of each character in string t
    t_index = {char: idx for idx, char in enumerate(t)}

    # Calculate the sum of absolute differences between indices for each character
    total_diff = 0
    for idx, char in enumerate(s):
        total_diff += abs(idx - t_index[char])

    return total_diff
