def countStableArrays(zero, one, limit):
    MOD = 10**9 + 7

    # dp[i][j][k] represents the number of stable arrays with i zeros, j ones, 
    # and ending with a run of k consecutive same bits (k can be 0 for last bit 0, 
    # or 1 for last bit 1, but we need to track the length of the current run)
    # Actually, let's use: dp[i][j][run_length][last_bit] where last_bit is 0 or 1

    # But since we only care about whether the last bit was 0 or 1 and the length of the current run,
    # we can use 3D DP: dp[i][j][last] where last is 0 or 1, and we need to store the run length

    # Better: dp[i][j][k] where k is the length of the current run (of same bits), and we need to know
    # which bit it is. So we can have two 2D arrays: dp0[i][j][k] for arrays ending with 0 with run length k,
    # and dp1[i][j][k] for arrays ending with 1 with run length k.

    # Dimensions: i from 0 to zero, j from 0 to one, k from 1 to limit

    # Initialize dp arrays
    dp0 = [[[0] * (limit + 1) for _ in range(one + 1)] for _ in range(zero + 1)]
    dp1 = [[[0] * (limit + 1) for _ in range(one + 1)] for _ in range(zero + 1)]

    # Base case: array with one element
    if zero >= 1:
        dp0[1][0][1] = 1
    if one >= 1:
        dp1[0][1][1] = 1

    # Fill the DP table
    for i in range(zero + 1):
        for j in range(one + 1):
            # Process dp0: arrays ending with 0
            for k in range(1, limit + 1):
                if i == 0:
                    continue

                # Current array ends with 0, run length k
                if k == 1:
                    # We added a 0 after a 1, so previous state must have ended with 1, any valid run length
                    for prev_k in range(1, limit + 1):
                        if j > 0:
                            dp0[i][j][k] = (dp0[i][j][k] + dp1[i-1][j][prev_k]) % MOD
                else:
                    # We added a 0 after a 0, so previous state must have ended with 0, run length k-1
                    dp0[i][j][k] = (dp0[i][j][k] + dp0[i-1][j][k-1]) % MOD

            # Process dp1: arrays ending with 1
            for k in range(1, limit + 1):
                if j == 0:
                    continue

                if k == 1:
                    # We added a 1 after a 0, so previous state must have ended with 0, any valid run length
                    for prev_k in range(1, limit + 1):
                        if i > 0:
                            dp1[i][j][k] = (dp1[i][j][k] + dp0[i][j-1][prev_k]) % MOD
                else:
                    # We added a 1 after a 1, so previous state must have ended with 1, run length k-1
                    dp1[i][j][k] = (dp1[i][j][k] + dp1[i][j-1][k-1]) % MOD

    # Sum all valid arrays with exactly zero zeros and one ones
    result = 0
    for k in range(1, limit + 1):
        result = (result + dp0[zero][one][k] + dp1[zero][one][k]) % MOD

    return result
```

