    dist = [[INF] * len(key_points) for _ in range(len(key_points))]

    # Directions
    dirs = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def bfs(start_pos):
        d = [[-1] * W for _ in range(H)]
        q = deque()
        si, sj = start_pos
        d[si][sj] = 0
        q.append((si, sj))

        while q:
            i, j = q.popleft()
            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] != '#' and d[ni][nj] == -1:
                    d[ni][nj] = d[i][j] + 1
                    q.append((ni, nj))
        return d

    # Compute distances between all key points
    for idx, kp in enumerate(key_points):
        d = bfs(kp)
        for jdx, other in enumerate(key_points):
            oi, oj = other
            dist[idx][jdx] = d[oi][oj]

    # If distance from start to goal is INF, impossible
    if dist[0][n+1] == INF:
        print(-1)
        return

    # If start can reach goal within T moves, at least we can go directly
    if dist[0][n+1] <= T:
        best = 0  # At least 0 candies possible
    else:
        print(-1)
        return

    # If no candies, answer is 0
    if n == 0:
        print(0)
        return

    # For permutations of candies, try all subsets (orderings)
    # We'll use DP with bitmask for TSP-like approach
    # dp[mask][i] = minimum moves to visit candies in mask, ending at candy i (index 1..n)
    # We'll also consider starting from start (index 0) and ending at goal (index n+1)

    # dp[mask][i] for i in [0, n-1] representing candies, mask in [0, 2^n)
    # i corresponds to candy index i (key point index = i+1)

    # Initialize: from start to each candy
    dp = [[INF] * n for _ in range(1 << n)]
    for i in range(n):
        if dist[0][i+1] <= T:
            dp[1 << i][i] = dist[0][i+1]

    # Fill dp
    for mask in range(1, 1 << n):
        for i in range(n):
            if not (mask & (1 << i)):
                continue
            if dp[mask][i] == INF:
                continue
            for j in range(n):
                if mask & (1 << j):
                    continue
                new_mask = mask | (1 << j)
                new_cost = dp[mask][i] + dist[i+1][j+1]
                if new_cost < dp[new_mask][j]:
                    dp[new_mask][j] = new_cost

    # Now try all masks, and from ending candy to goal
    for mask in range(1 << n):
        for i in range(n):
            if dp[mask][i] == INF:
                continue
            total_moves = dp[mask][i] + dist[i+1][n+1]  # to goal
            if total_moves <= T:
                # count bits in mask
                cnt = bin(mask).count('1')
                if cnt > best:
                    best = cnt

    print(best)

