def punishment_number(n):
    def can_partition(s, target):
        """Check if string s can be partitioned into contiguous substrings whose integer values sum to target."""
        def backtrack(index, current_sum):
            if index == len(s):
                return current_sum == target

            num = 0
            for i in range(index, len(s)):
                num = num * 10 + int(s[i])
                # Early pruning: if current sum already exceeds target, skip
                if current_sum + num > target:
                    break
                if backtrack(i + 1, current_sum + num):
                    return True
            return False

        return backtrack(0, 0)

    total = 0
    for i in range(1, n + 1):
        square = i * i
        square_str = str(square)
        if can_partition(square_str, i):
            total += square

    return total
