def shortest_beautiful_substring(s, k):
    n = len(s)
    min_len = float('inf')
    candidates = []

    # Sliding window to find all substrings with exactly k '1's
    for i in range(n):
        count_ones = 0
        for j in range(i, n):
            if s[j] == '1':
                count_ones += 1
            if count_ones == k:
                # We found a beautiful substring from i to j
                length = j - i + 1
                substring = s[i:j+1]

                if length < min_len:
                    min_len = length
                    candidates = [substring]
                elif length == min_len:
                    candidates.append(substring)
                # Since we're looking for shortest, break once we find k ones for this start index
                # because extending further would only make it longer
                break

    if not candidates:
        return ""

    # Find lexicographically smallest among candidates with minimum length
    return min(candidates)
