def canSplitArray(nums, m):
    n = len(nums)

    # If the array has length 1, it's already split into n=1 arrays
    if n == 1:
        return True

    # Precompute prefix sums for efficient subarray sum calculation
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]

    # Helper function to get sum of subarray from index l to r (inclusive)
    def subarray_sum(l, r):
        return prefix[r + 1] - prefix[l]

    # Memoization cache for recursive function
    memo = {}

    def can_split(l, r):
        # Base case: single element - already split
        if l == r:
            return True

        # If subarray length is 2, we can always split it:
        # Either one part is length 1 (valid), or both parts need sum >= m
        # But we can always split a 2-element array into [a] and [b], both length 1 (valid)
        if r - l == 1:
            return True

        # Check if already computed
        if (l, r) in memo:
            return memo[(l, r)]

        # Try all possible split positions
        for k in range(l, r):
            # Left part: [l, k], right part: [k+1, r]
            left_len = k - l + 1
            right_len = r - k

            left_valid = (left_len == 1) or (subarray_sum(l, k) >= m)
            right_valid = (right_len == 1) or (subarray_sum(k + 1, r) >= m)

            if left_valid and right_valid:
                # If this split is valid, check if both parts can be further split
                if can_split(l, k) and can_split(k + 1, r):
                    memo[(l, r)] = True
                    return True

        memo[(l, r)] = False
        return False

    return can_split(0, n - 1)
