from math import gcd
from collections import defaultdict, deque

def can_traverse_all_pairs(nums):
    n = len(nums)

    # Edge case: single element
    if n == 1:
        return True

    # If any element is 1, it cannot connect to any other index (gcd(1, x) = 1 for x > 1)
    if 1 in nums:
        return False

    # Build a graph where each index is connected to others if gcd > 1
    # However, directly checking all pairs is O(n^2) which is too slow for n up to 10^5
    # Instead, use union-find or BFS with prime factorization

    # Union-Find approach:
    # Connect indices that share a common prime factor

    # First, get all prime factors for each number and map prime -> list of indices
    prime_to_indices = defaultdict(list)

    # Function to get prime factors
    def get_prime_factors(x):
        factors = set()
        d = 2
        while d * d <= x:
            if x % d == 0:
                factors.add(d)
                while x % d == 0:
                    x //= d
            d += 1
        if x > 1:
            factors.add(x)
        return factors

    # Map each prime factor to indices that contain it
    for i, num in enumerate(nums):
        factors = get_prime_factors(num)
        for p in factors:
            prime_to_indices[p].append(i)

    # Union-Find data structure
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return
        if rank[px] < rank[py]:
            parent[px] = py
        elif rank[px] > rank[py]:
            parent[py] = px
        else:
            parent[py] = px
            rank[px] += 1

    # For each prime factor, union all indices that have this prime factor
    for prime, indices in prime_to_indices.items():
        if len(indices) > 1:
            first = indices[0]
            for i in range(1, len(indices)):
                union(first, indices[i])

    # Check if all indices belong to the same connected component
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False

    return True
