def maximumPrimeDistance(nums):
    # Helper function to check if a number is prime
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        # Check odd divisors up to sqrt(n)
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Find the first and last indices of prime numbers
    first_prime_idx = -1
    last_prime_idx = -1

    for i, num in enumerate(nums):
        if is_prime(num):
            if first_prime_idx == -1:
                first_prime_idx = i
            last_prime_idx = i

    return last_prime_idx - first_prime_idx
