def specialPerm(nums):
    MOD = 10**9 + 7
    n = len(nums)

    # Precompute compatibility: compat[i][j] = True if nums[i] and nums[j] satisfy the condition
    compat = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                compat[i][j] = (nums[i] % nums[j] == 0) or (nums[j] % nums[i] == 0)

    # dp[mask][i] = number of ways to form a sequence ending with element i, using the set of elements represented by mask
    # mask is a bitmask where bit j is 1 if element j is used
    dp = {}

    # Base case: sequences of length 1
    for i in range(n):
        dp[(1 << i, i)] = 1

    # Iterate over all masks
    for mask in range(1, 1 << n):
        for last in range(n):
            if not (mask & (1 << last)):
                continue
            if (mask, last) not in dp:
                continue

            # Try to extend the sequence with an unused element
            for next_idx in range(n):
                if mask & (1 << next_idx):
                    continue
                if not compat[last][next_idx]:
                    continue

                new_mask = mask | (1 << next_idx)
                key = (new_mask, next_idx)
                dp[key] = (dp.get(key, 0) + dp[(mask, last)]) % MOD

    # Sum all complete permutations (all elements used)
    full_mask = (1 << n) - 1
    result = 0
    for last in range(n):
        result = (result + dp.get((full_mask, last), 0)) % MOD

    return result
